class A { static s: number = 1; static t: string = 'a'; }
class B extends A {}
class C extends B {}
async function main(): Promise<void> {
  B.s = 10;
  console.log(A.s, B.s, C.s);
  C.s = 20;
  console.log(A.s, B.s, C.s);
  A.s = 5;
  console.log(A.s, B.s, C.s);
  B.t += 'x';
  console.log(A.t, B.t, C.t);
}
